```java
import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;

import java.util.concurrent.TimeUnit;

public class UISelectorExample {
    public static void main(String[] args) {
        // 创建 Chrome 驱动器
        System.setProperty("webdriver.chrome.driver", "/path/to/chromedriver");
        WebDriver driver = new ChromeDriver();

        // 打开网页
        driver.get("https://www.example.com");

        // 输入 XPath 表达式
        String xpathExpression = "//div[@class='example-class']";

        // 使用 Selenium WebDriver 找到元素
        WebElement element = driver.findElement(By.xpath(xpathExpression));

        // 创建 UISelector 对象
        UISelector selector = new UISelector(element);

        // 输出 UISelector 的描述和 XPath 表达式
        System.out.println("UISelector description: " + selector.getDescription());
        System.out.println("XPath expression: " + xpathExpression);

        // 等待页面加载完成
        WebDriverWait wait = new WebDriverWait(driver, 10);
        wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath(xpathExpression)));

        // 关闭驱动器
        driver.quit();
    }
}
```
